"""Writes data/town_sizes.json: the people of history's great towns through the ages (run from the repository root)."""
import json
T = []
def t(name, lon, lat, sizes, note=""):
    T.append({"name": name, "lon": lon, "lat": lat, "sizes": [[y, p] for y, p in sizes], "note": note})
